import sys
sys.dont_write_bytecode=True
import additional_pfp_domain_remaining_audit as a
n=a.read('_notes.json');n['controls'].extend(a.read('_certificate_probes.json')['controls'])
def ev(path,*ranges):return {'path':path,'sha256':a.row(path)['sha256'],'lines':[list(x) for x in ranges]}
for id,title,statement,ranges,controls in [
('PFPDOMAIN-F022','Proofreading admits arithmetic-looking pseudo-prose without a mathematical check','The HopfieldNinioProofreader describes preventing pseudo-proofs and surviving orthogonal deformation, but its actual predicate is marker/buzzword detection plus caller-supplied residual. Appending the false equation1=2 to gauge-invariance/topological-protection prose changes DISSOCIATED_DURING_DELAY to CATALYTIC_ADMISSION at default zero residual. No equation truth, proof, deformation or kinetic process is checked. This is heuristic evidence, not proof admission.',[(86,91),(116,175)],['PFPDOMAIN-C029']),
('PFPDOMAIN-F023','Proofreading accepts negative parameters and emits contradictory measurements','Negative deformation_factor is admitted and copied as delta; the receipt reason still states measured Delta Phi_1=-1 >0. A negative initial residual on unflagged text is silently rewritten as zero in the admission receipt. Energy_per_delay is also unconstrained in sign. Thus accepted input values can violate the record own claimed nonnegative defect/dissipation semantics.',[(93,114),(134,175)],['PFPDOMAIN-C030'])]:
 e=ev('pfp/domain/biochem/proofreading.py',*ranges);n['findings'].append({'id':id,'title':title,'statement':statement,'evidence':[e['path']],'source_evidence':[e],'control_ids':controls,'status':'confirmed_bounded_source_and_probe','limits':'Focused local Fraction/text controls, not a test of model, physical biochemical behavior or a downstream host gate.'})
for id,title,statement,evidence,controls in [
('PFPDOMAIN-CL07','Exact weighted-L1 duality is a real conditional optimality mechanism','The certificate predicate checks rational dimensions, z=omega-Dalpha, D^T W=0, |W|<=w, sign alignment and equal primal/dual reported objectives. These imply global minimization by the dual lower bound for every alternative alpha. It establishes the supplied finite optimization problem, not source interpretation, unique solution or semantic repair; zero weights yield a seminorm and permit nonzero residual at zero optimum.',[ev('pfp/domain/dual_witness/models.py',(15,117))],['PFPDOMAIN-C027']),
('PFPDOMAIN-CL08','Tower lift lower bounds depend on explicit cardinality and distinctness','Exhausting all2 and16 binary relations on canonical one/two-element carriers confirms the supplied predicates: no irreflexive witnessed pair on one element, no path2/cycle3 with three distinct vertices on two. This is a finite combinatorial consequence of admitted definitions, not a derivation of the carrier/logic/stages from primitive difference. Stored receipt pins alone do not bind counts or target witnesses.',[ev('pfp/domain/tower_lift/models.py',(16,77),(85,108))],['PFPDOMAIN-C028'])]:
 n['claims'].append({'id':id,'title':title,'statement':statement,'evidence':[x['path'] for x in evidence],'source_evidence':evidence,'control_ids':controls,'status':'bounded_scope_assessment'})
a.write('_notes.json',n);a.report()
